fn apply<F>(f: F) where
    F: Fn() {
    f();
}

// Fonction qui utilise un trait FnMut
fn mut_apply<F>(f: F) where
    F: FnMut() {
    f.call_mut();
}

// Fonction qui utilise un trait FnOnce
fn once_apply<F>(f: F) where
    F: FnOnce() {
    f.call_once();
}
```

